-- Inside Grey Room v66 — contextual role-card audit.
-- Replaces generic institutional guidance with scenario-grounded discussion
-- material in the scenarios where specialist roles actually appear.
-- Existing canonical facts and gameplay rules remain unchanged.

do $$
declare s record; r record; patch jsonb := $json${"013":{"role_notes":{"analyste":{"anchors":"La chaîne est cloisonnée : un acteur peut connaître le véhicule sans connaître le tireur, ou la faille de sécurité sans connaître le commanditaire.","position":"Repère quelles informations étaient compartimentées et lesquelles supposent un contact entre deux maillons."},"procureur":{"anchors":"Le tir matériel est établi séparément de la préparation. Relie financement, véhicule, accès et faille de sécurité sans confondre auteur du tir et organisateur.","position":"Cherche une chaîne probante entre les maillons ; n’utilise pas la gravité de l’assassinat pour combler les liens manquants."}}},"014":{"role_notes":{"analyste":{"anchors":"La fuite finale provient d’au moins deux sources numériques. Compare ce que chaque suspect pouvait extraire, reconstituer, transmettre ou falsifier.","position":"Repère les faits qui nécessitent plusieurs personnes et ceux qu’un seul acteur pouvait accomplir."},"juge":{"anchors":"Quatre éléments peuvent être protégés, mais protection et culpabilité sont deux questions différentes. Les exports, la fusion de sources et les logs falsifiés doivent être datés séparément.","position":"Arbitre l’accès sans laisser le statut classifié d’un élément lui donner plus de valeur probante qu’il n’en a."}}},"015":{"role_notes":{"enqueteur":{"anchors":"Reconstitue l’ordre alertes → demande de suspension → décision de poursuivre → décès → modification du dossier. Le moment où chacun apprend le risque est central.","position":"Fais préciser ce qui était connu avant la mort et ce qui relève uniquement de la couverture après les faits."},"analyste":{"anchors":"Une même personne peut avoir exprimé une inquiétude puis agir à l’inverse. Compare les écrits, les réunions et les décisions plutôt que la cohérence apparente des discours.","position":"Repère quand une hésitation devient une décision assumée et quand une justification apparaît seulement après le décès."},"juge":{"anchors":"Les pièces protégées peuvent contenir des informations médicales sensibles sans être décisives sur la responsabilité. Leur portée dépend surtout de la date et du destinataire.","position":"Protège ce qui doit l’être sans empêcher l’enquête de comparer qui connaissait les alertes et quand."},"journaliste":{"anchors":"Ta source interne est Nina Valès. Les alertes médicales, la réunion budgétaire et les modifications postérieures au décès sont trois angles distincts : ne les fusionne pas sans preuve.","position":"Cherche ce qui peut être rendu public sans exposer inutilement ta source ni transformer un document isolé en accusation."}}},"016":{"role_notes":{"enqueteur":{"anchors":"La vidéo prouve l’enlèvement, la drogue et l’humiliation, mais s’arrête avant le geste fatal. Distingue ce qui est filmé, ce qui se produit hors champ et ce qui est effacé ensuite.","position":"Fais reconstruire les dix-sept minutes manquantes et les départs du dernier étage sans supposer que l’organisateur est forcément le meurtrier."},"analyste":{"anchors":"Deux voix, deux badges et une silhouette tardive ne racontent pas nécessairement la même histoire. Compare surtout les changements de présence après l’arrêt de la vidéo.","position":"Repère qui adapte son récit aux images connues et qui possède une information sur la période hors champ."},"maitre":{"anchors":"Ton client peut être responsable de l’enlèvement, de la mise en scène ou d’une aide matérielle sans être l’auteur du geste fatal. Les degrés doivent rester séparés.","position":"Défends la frontière exacte entre participation au dispositif et décision de tuer, sans nier les faits filmés."},"juge":{"anchors":"Les éléments protégés peuvent éclairer la période hors champ, mais une protection n’est ni un acquittement ni une accusation.","position":"Arbitre l’accès en gardant séparées les responsabilités pour l’enlèvement, l’humiliation, le meurtre et l’effacement."},"journaliste":{"anchors":"La vidéo est spectaculaire mais incomplète. Une publication responsable doit distinguer ce qui est visible, ce qui est techniquement établi et ce qui reste une hypothèse.","position":"Mets la pression sur les contradictions publiques sans attribuer le meurtre à partir des seules images."}}},"017":{"role_notes":{"enqueteur":{"anchors":"Replace dans l’ordre la séquestration, la détresse, l’appel, la mort, le paiement puis la libération. La responsabilité peut changer entre ces étapes.","position":"Fais préciser qui pouvait arrêter la violence ou appeler les secours au moment où l’état de la victime se dégrade."},"analyste":{"anchors":"Les menaces imposées au survivant arrivent après la séquence mortelle. Ne confonds pas dissimulation postérieure, commandement de l’opération et geste physique.","position":"Compare ce que chaque acteur sait avant et après l’appel signalant que la victime respire mal."},"procureur":{"anchors":"Une coopération crédible doit apporter un détail vérifiable sur le lieu, l’appel, le paiement ou la chaîne de décision. La peur du survivant explique un silence, pas automatiquement la vérité de tout son récit.","position":"Distingue auteur matériel, organisateur, retard des secours et dissimulation dans les poursuites proposées."},"temoin":{"anchors":"Tu peux décrire ce que tu as vu, entendu et subi pendant la séquestration. Tu ne connais pas nécessairement l’origine de chaque ordre.","position":"Reste sur ton expérience directe ; une menace peut expliquer ton silence initial sans te donner accès à toute la chaîne."}}},"018":{"role_notes":{"enqueteur":{"anchors":"Deux questions restent séparées : qui cause la mort et qui transforme ensuite la scène. La chronologie du mobilier, des assiettes et des traces est plus utile que la symbolique seule.","position":"Fais expliquer à chacun ce qu’il savait de la scène avant et après le décès."},"analyste":{"anchors":"Un comportement étrange autour des neuf assiettes peut cacher une mise en scène, un vol ou une tentative de protection sans désigner le meurtrier.","position":"Compare les raisons de mentir et les moments de présence ; ne traite pas toute dissimulation comme une preuve d’homicide."},"inspecteur":{"anchors":"Le terrain doit distinguer la scène initiale de ce qui a été ajouté ou déplacé après la mort. Cherche des traces de passage, de transport et de manipulation.","position":"Rapporte ce que les lieux prouvent matériellement et laisse l’Enquêteur relier ces traces aux versions humaines."}}},"019":{"role_notes":{"enqueteur":{"anchors":"Sépare la volonté de faire taire le lanceur d’alerte, les moyens préparés pour l’isoler, l’accès à la victime et la décision finale de tuer.","position":"Fais préciser à chacun ce qu’il comprenait réellement derrière l’ordre de « ne pas laisser parler »."},"analyste":{"anchors":"Un ordre ambigu peut être interprété, aggravé ou instrumentalisé. Compare le langage employé avant le gala avec les choix concrets pendant la fenêtre sans caméra.","position":"Repère le moment où une stratégie de pression devient une décision homicide."},"procureur":{"anchors":"La volonté d’empêcher une révélation est établie plus facilement que l’ordre de tuer. Cherche le lien entre pression, moyens fournis et décision opérationnelle.","position":"Poursuis séparément commanditaire de la pression, auteur matériel et personnes ayant couvert les faits."},"juge":{"anchors":"Les éléments protégés peuvent concerner le dossier du lanceur d’alerte ou les circuits de sécurité. Leur sens doit rester distinct de la preuve du meurtre.","position":"Arbitre sans confondre intérêt institutionnel à faire taire la victime et ordre explicite de la tuer."},"maitre":{"anchors":"Un client peut avoir voulu empêcher une prise de parole sans avoir voulu un meurtre. L’enquête doit démontrer le passage de l’objectif au moyen létal.","position":"Défends la limite entre pression, facilitation et homicide sans nier les actes matériels établis."},"journaliste":{"anchors":"Le dossier manquant et la mort du lanceur d’alerte créent une histoire forte, mais les messages disponibles ne contiennent pas d’ordre explicite de tuer.","position":"Publie ce qui est sourcé sur les pressions et les accès sans transformer le contexte politique en preuve du geste fatal."}}},"020":{"role_notes":{"enqueteur":{"anchors":"Le bilan de 327 morts vient d’une chaîne : départ du feu, détection, sorties, systèmes, matériaux et retard d’évacuation. Aucun maillon ne suffit seul.","position":"Fais préciser ce que chaque acteur savait avant l’incendie et quelles décisions restaient possibles pendant les premières minutes."},"analyste":{"anchors":"Une intention limitée peut produire une catastrophe lorsqu’elle rencontre des défaillances connues. Compare intention, prévisibilité et capacité d’intervention.","position":"Repère les acteurs qui minimisent leur rôle en regardant seulement leur propre maillon de la chaîne."},"inspecteur":{"anchors":"Le terrain doit documenter les sorties, systèmes, matériaux et propagation sans transformer une anomalie technique en intention humaine.","position":"Apporte des faits localisés et datés qui permettront de relier les décisions aux conséquences."},"procureur":{"anchors":"La gravité du bilan ne permet pas d’attribuer la même responsabilité à tous. Relie chaque poursuite à une décision, une connaissance du risque ou une omission démontrable.","position":"Distingue incendie volontaire, non-conformité connue, verrouillage et retard d’évacuation."},"juge":{"anchors":"Les pièces protégées peuvent toucher à la sécurité, aux contrats ou aux victimes. Leur sens doit être évalué dans la chaîne causale, pas isolément.","position":"Arbitre les responsabilités selon les décisions concrètes et le niveau de connaissance de chacun."},"expert":{"anchors":"Tes analyses portent sur la propagation, les systèmes et la chronologie technique. Elles peuvent expliquer comment le bilan s’aggrave, jamais désigner seules qui voulait quoi.","position":"Donne des conclusions techniques bornées et explicite ce qu’elles ne permettent pas d’inférer."},"maitre":{"anchors":"Ton client peut être responsable d’un maillon grave sans être responsable de toute la catastrophe. La chaîne causale doit rester segmentée.","position":"Défends la part exacte de connaissance, de contrôle et de décision de ton client sans nier l’effet de son propre maillon."},"journaliste":{"anchors":"Le chiffre de 327 morts ne doit pas écraser la chronologie. Distingue les alertes antérieures, les décisions de sécurité et les choix faits pendant l’évacuation.","position":"Publie les responsabilités documentées sans réduire une catastrophe systémique à un seul visage trop tôt."},"temoin":{"anchors":"Tu apportes un récit situé : ce que tu as vu, entendu ou tenté pendant l’incendie. Tu ne connais pas nécessairement les décisions prises ailleurs.","position":"Aide à dater les conséquences concrètes des choix de sécurité sans spéculer sur les intentions des décideurs."}}},"026":{"role_notes":{"enqueteur":{"position":"Maintiens la reconstruction judiciaire malgré la dégradation extérieure ; distingue responsabilité passée et information sur la cellule encore active."},"analyste":{"position":"Compare ce que chaque détenu sait réellement du réseau avec la manière dont la peur, le calcul ou l’idéologie influencent sa coopération."},"expert":{"anchors":"Recoupe les sources, les communications et les niveaux de confiance sur la structure encore active. Une concordance de réseau n’est pas une instruction opérationnelle.","position":"Établis quels liens sont confirmés, probables ou seulement déclarés et transmets cette hiérarchie à l’enquête."},"procureur":{"anchors":"Une coopération n’a de valeur que si elle apporte un élément vérifiable sur les atrocités passées ou la continuité du réseau. L’urgence extérieure ne réduit pas automatiquement la responsabilité.","position":"Négocie sur la qualité des informations et la responsabilité réelle, pas sur la peur créée par le périmètre."}}},"027":{"role_notes":{"enqueteur":{"position":"Établis d’abord les responsabilités dans les massacres ; la décision militaire utilisera ensuite tes conclusions sans transformer le verdict en choix tactique."},"analyste":{"position":"Sépare exactitude de l’information et intérêt de la source : un suspect peut dire vrai pour faire frapper ses rivaux."},"procureur":{"anchors":"Une coopération très précise sur les rivaux doit être recoupée comme n’importe quelle autre source. L’utilité militaire d’une information ne prouve pas la sincérité globale du coopérant.","position":"Cherche des informations vérifiables sur les responsabilités passées sans récompenser la simple sélection stratégique de vérités."},"inspecteur":{"anchors":"Relie les données de la cellule de crise à des faits humains : présence récente, civils possibles, otages et incertitude du renseignement. Aucun détail tactique supplémentaire n’est nécessaire.","position":"Porte une évaluation de confiance vers la décision finale, sans décider à la place de l’enquête."},"expert":{"anchors":"Compare les sources sur la présence du commandement, les civils et les otages en indiquant clairement ancienneté et niveau de confiance.","position":"Une information vraie mais ancienne doit être présentée comme telle ; ne transforme pas l’absence de contradiction en présence actuelle."}}},"028":{"role_notes":{"enqueteur":{"position":"Cherche ce qui relie réellement les détenus à la cellule intérieure sans confondre calme, coopération ou peur avec une preuve."},"analyste":{"position":"Compare les deux coopérations concordantes avec le comportement du troisième suspect, tout en gardant chaque élément comportemental au rang d’hypothèse."},"procureur":{"anchors":"Deux détenus peuvent coopérer sincèrement et rester responsables d’actes antérieurs. Une information sur la cellule intérieure doit être vérifiable indépendamment.","position":"Évalue ce que chaque coopération apporte réellement avant toute concession ou accusation."},"inspecteur":{"anchors":"Les communications intermittentes et les accès antérieurs peuvent produire des données incomplètes. Distingue absence de signal, signal retardé et preuve positive d’une présence intérieure.","position":"Apporte des repères de terrain et de liaison sans surinterpréter les coupures du périmètre."},"expert":{"anchors":"Recoupe les signaux indépendants qui rendent une présence intérieure plausible et indique ce qui reste non confirmé.","position":"Aide l’enquête à passer de « possible » à « étayé » sans présenter une hypothèse de réseau comme une certitude."}}}}$json$::jsonb;
begin
 for s in select key,value from jsonb_each(patch) loop
   for r in select key,value from jsonb_each(coalesce(s.value->'role_notes','{}'::jsonb)) loop
     update public.igr_v4_scenario_packs
     set pack=jsonb_set(
       pack,
       array['role_notes',r.key],
       coalesce(pack #> array['role_notes',r.key],'{}'::jsonb) || r.value,
       true
     )
     where scenario_id=s.key;
   end loop;
 end loop;
end $$;
